describe('Login Page Password Validation', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/login');
  });

  it('should display error message when submitting wrong password', () => {
    cy.get('[data-testid="username-input"]').type('tomsmith');
    cy.get('[data-testid="password-input"]').type('wrongpassword');
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/login');
    cy.get('[data-testid="flash-error"]').should('be.visible');
    cy.get('[data-testid="flash-error"]').should('contain', 'Your password is invalid!');
    cy.get('[data-testid="flash-error"]').should('have.class', 'flash-error');
  });

  it('should not navigate away when password is invalid', () => {
    cy.get('[data-testid="username-input"]').type('tomsmith');
    cy.get('[data-testid="password-input"]').type('wrongpassword');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="login-form"]').should('be.visible');
    cy.get('[data-testid="flash-error"]').should('be.visible');
    cy.get('[data-testid="flash-error"]').should('contain', 'Your password is invalid!');
    cy.get('[data-testid="login-button"]').should('be.visible');
  });
});
